  "name": "umbraco.bench.frontend",
  "private": true,
  "type": "module",
  "scripts": {
    "build": "vite build",
    "watch": "vite build --watch"
  },
  "dependencies": {
    "vue": "^3.5.0"
  },
  "devDependencies": {
    "@tailwindcss/vite": "^4.0.0",
    "@vitejs/plugin-vue": "^6.0.0",
    "tailwindcss": "^4.0.0",
    "typescript": "^5.0.0",
    "vite": "^8.0.0"
  }
}
@import "tailwindcss";

/* Tailwind scans these for class names. Razor views live outside this project,
   so they need an explicit @source; everything under src/ is picked up as well. */
@source "../../Umbraco.Bench.Umbraco/Views";

/* Site-wide styles below. Vue custom elements have their own shadow-DOM styles,
   but content passed into their slots renders in the light DOM and is styled here. */
import { defineConfig } from "vite";
import vue from "@vitejs/plugin-vue";
import tailwindcss from "@tailwindcss/vite";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = fileURLToPath(new URL(".", import.meta.url));
const outDir = resolve(__dirname, "../Umbraco.Bench.Umbraco/wwwroot/dist");

export default defineConfig({
    // *.ce.vue components compile in custom-element mode: their <style> blocks are
    // inlined into the element's shadow root. Site-wide styling is Tailwind: site.css
    // scans both Razor views and Vue components (see @source in src/site.css).
    plugins: [vue(), tailwindcss()],
    build: {
        outDir,
        emptyOutDir: true,
        sourcemap: true,
        rollupOptions: {
            input: {
                main: resolve(__dirname, "src/main.ts"),
                site: resolve(__dirname, "src/site.css"),
            },
            output: {
                entryFileNames: "[name].js",
                chunkFileNames: "chunks/[name].js",
                assetFileNames: "[name][extname]",
            },
        },
    },
});
