@inherits UmbracoViewPage<BlockGridItem<BlogPostListBlock>>
@{
    var posts = UmbracoContext.PublishedRequest?.PublishedContent?
        .Children<BlogPost>()
        .OrderByDescending(post => post.PublishDate)
        .ToList() ?? [];
    if (Model.Content.MaxPosts > 0)
    {
        posts = posts.Take(Model.Content.MaxPosts).ToList();
    }

    var model = new BlogPostListModel
    {
        Heading = Model.Content.Heading,
        Posts = posts.Select(post => new PostSummaryModel
        {
            Title = post.Name,
            Summary = post.Summary ?? "",
            Url = post.Url(),
            PublishedOn = post.PublishDate,
            ImageUrl = post.HeroImage?.GetCropUrl(width: 800, height: 450),
        }).ToList(),
    };
}
@await Component.InvokeAsync("BlogPostList", new { model })

