@model BlogPostListModel

<section class="mx-auto max-w-5xl px-6 py-16">
    @if (!string.IsNullOrWhiteSpace(Model.Heading))
    {
        <h2 class="mb-10 text-3xl font-bold tracking-tight text-slate-900">@Model.Heading</h2>
    }
    @if (Model.Posts.Count == 0)
    {
        <p class="text-slate-500">No posts yet.</p>
    }
    <ul class="grid gap-10 md:grid-cols-2">
        @foreach (var post in Model.Posts)
        {
            <li class="group overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm transition hover:shadow-lg">
                <a href="@post.Url" class="block">
                    @if (!string.IsNullOrEmpty(post.ImageUrl))
                    {
                        <img src="@post.ImageUrl" alt="" class="aspect-video w-full object-cover" loading="lazy" />
                    }
                    <div class="p-6">
                        <time datetime="@post.PublishedOn.ToString("yyyy-MM-dd")" class="text-sm text-slate-500">@post.PublishedOn.ToString("d MMMM yyyy")</time>
                        <h3 class="mt-2 text-xl font-semibold text-slate-900 group-hover:text-indigo-600">@post.Title</h3>
                        <p class="mt-3 text-slate-600">@post.Summary</p>
                        <span class="mt-4 inline-block text-sm font-medium text-indigo-600">Read the post &rarr;</span>
                    </div>
                </a>
            </li>
        }
    </ul>
</section>

